// Map whichever trigger fired to the Arena jobs it owns.
// Every job is idempotent and self-gating: it finds its own work and reports
// `skipped` when there is none, so firing more often than needed is safe and
// firing late is recoverable.
const byTrigger = {
  'Every 2 minutes': ['reviews-run'],
  'Daily 08:00 WIB': ['email-flush', 'week-notifications'],
  'Daily 01:30 WIB': ['session-cleanup', 'storage-cleanup'],
  'Sunday 09:00 WIB': ['project-generate'],
  'Hourly project publication': ['project-drop'],
  'Saturday 00:05 WIB': ['week-close'],
  'Weekend every 2h': ['week-finalize'],
};

// $prevNode.name is the trigger that started this execution.
const source = $prevNode.name;
const jobs = byTrigger[source];
if (!jobs) throw new Error(`No Arena jobs mapped for trigger "${source}"`);

return jobs.map((job) => ({ json: { job, source } }));

// Surface only what a human would act on. A job reporting `skipped` is the
// normal quiet case and is not an alert.
const out = [];
for (const item of $input.all()) {
  const status = item.json.statusCode;
  const body = item.json.body ?? {};
  const data = body.data ?? {};
  const failed = status !== 200 || data.done === false;
  out.push({
    json: {
      job: data.job ?? 'unknown',
      status,
      ok: !failed,
      detail: data.detail ?? body.error ?? null,
    },
  });
}
return out;
